#include "vibesolaris.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static int calls,actions,reject_batch,missing_task_id,question_mode;
static char *dup(const char*s){size_t n=strlen(s);char*p=malloc(n+1);if(p)memcpy(p,s,n+1);return p;}
char *vs_chat(VSContext*c,const char*p){(void)c;(void)p;calls++;if(question_mode&&calls==1){if(question_mode==2)return dup("[[VS_NEED_USER question=\"Legacy question\"]]");if(question_mode==3)return dup("[[VS_NEED_USER question=\"Malformed choices\" option1=\"Valid\" option2=\"\"]]");return dup("[[VS_NEED_USER question=\"Choose an environment\" option1=\"Development\" option2=\"Production\"]]");}if(question_mode==1&&calls==2){if(strstr(p,"Production"))return dup("[[VS_FINAL]]selected production");return dup("[[VS_FINAL]]missing selection");}if(missing_task_id&&calls>1)return dup("[[VS_TOOL run cmd=\"printf test\"]]");if(reject_batch)return dup("[[VS_TOOL run task_id=\"1\" cmd=\"printf test\"]][[VS_TOOL unknown value=\"x\"]]");if(calls==1)return dup("[[VS_PLAN title=\"Safe change\" tasks=\"1|0|-|Implement safe change\"]]");if(calls==2)return dup("[[VS_TOOL run task_id=\"1\" cmd=\"printf test\"]]");return dup("[[VS_FINAL]]done");}
void vs_trace(VSContext*c,const char*k,const char*d){(void)c;(void)k;(void)d;}void vs_trace_clear(VSContext*c){(void)c;}
int vs_mcp_refresh_all(VSContext*c,int f){(void)c;(void)f;return 0;}char *vs_compact_text_limit(const char*s,size_t n,const char*r){(void)n;(void)r;return dup(s?s:"");}void vs_history_add(VSContext*c,const char*r,const char*x){(void)c;(void)r;(void)x;}void vs_history_clear(VSContext*c){(void)c;}void vs_cache_clear(VSContext*c){(void)c;}int vs_cancel_requested(const VSContext*c){(void)c;return 0;}
char *vs_run_command(const char*cmd,int*st){(void)cmd;actions++;*st=0;return dup("ran");}char *vs_run_command_ctx(VSContext*c,const char*cmd,int*st){(void)c;return vs_run_command(cmd,st);}const char *vs_command_shell_name(void){return "sh";}
int vs_write_file(const char*p,const char*t){(void)p;(void)t;actions++;return 0;}int vs_attach(VSContext*c,const char*p){(void)c;(void)p;return 0;}int vs_is_image_path(const char*p){(void)p;return 1;}char *vs_cached_read_file(VSContext*c,const char*p){(void)c;(void)p;return dup("read");}void vs_cache_invalidate(VSContext*c,const char*p){(void)c;(void)p;}int vs_graph_build(VSContext*c,const char*r,VSGraphMode m,VSGraph*g){(void)c;(void)r;(void)m;(void)g;return 0;}char *vs_graph_summary(const VSGraph*g,int n){(void)g;(void)n;return dup("");}char *vs_web_search(VSContext*c,const char*q,int n){(void)c;(void)q;(void)n;return dup("");}char *vs_web_fetch(VSContext*c,const char*u,size_t n){(void)c;(void)u;(void)n;return dup("");}char *vs_mcp_call(VSContext*c,const char*s,const char*t,const char*a){(void)c;(void)s;(void)t;(void)a;actions++;return dup("mcp");}
int main(void){VSContext c;char*out;memset(&c,0,sizeof(c));vs_workflow_init(&c.workflow);out=vs_agent_turn(&c,"implement safe change");if(!out||c.workflow.phase!=VS_WORKFLOW_AWAITING_ACCEPT||actions||!strstr(out,"Plan is ready")){fprintf(stderr,"proposal did not pause safely: %s\n",out?out:"(null)");free(out);return 1;}free(out);if(vs_workflow_accept(&c.workflow)!=0)return 2;calls=1;out=vs_agent_turn(&c,"continue accepted work");if(!out||actions!=1||strcmp(out,"done")){fprintf(stderr,"accepted continuation result: %s actions=%d\n",out?out:"(null)",actions);free(out);return 3;}free(out);memset(&c,0,sizeof(c));vs_workflow_init(&c.workflow);calls=actions=0;out=vs_agent_turn(&c,"implement safe change");if(!out||c.workflow.phase!=VS_WORKFLOW_AWAITING_ACCEPT){free(out);return 4;}free(out);if(vs_workflow_accept(&c.workflow)!=0)return 5;calls=1;reject_batch=1;out=vs_agent_turn(&c,"continue accepted work");if(!out||actions!=0||!strstr(out,"malformed")){fprintf(stderr,"mixed batch was not rejected atomically: %s actions=%d\n",out?out:"(null)",actions);free(out);return 6;}free(out);memset(&c,0,sizeof(c));vs_workflow_init(&c.workflow);calls=actions=0;reject_batch=0;missing_task_id=0;out=vs_agent_turn(&c,"implement safe change");if(!out||c.workflow.phase!=VS_WORKFLOW_AWAITING_ACCEPT){free(out);return 7;}free(out);if(vs_workflow_accept(&c.workflow)!=0)return 8;calls=1;missing_task_id=1;out=vs_agent_turn(&c,"continue accepted work");if(!out||actions!=0||!strstr(out,"task_id")){fprintf(stderr,"missing task_id was not rejected: %s actions=%d\n",out?out:"(null)",actions);free(out);return 9;}free(out);memset(&c,0,sizeof(c));vs_workflow_init(&c.workflow);calls=actions=0;question_mode=1;out=vs_agent_turn(&c,"choose environment");if(!out||!c.pending_question||c.question_option_count!=2||strcmp(c.question_options[1],"Production")){fprintf(stderr,"question options were not preserved: %s\n",out?out:"(null)");free(out);return 10;}free(out);calls=1;out=vs_agent_turn(&c,"Production");if(!out||strcmp(out,"selected production")||actions){fprintf(stderr,"question answer did not resume: %s\n",out?out:"(null)");free(out);return 11;}free(out);question_mode=0;memset(&c,0,sizeof(c));vs_workflow_init(&c.workflow);calls=actions=0;missing_task_id=0;reject_batch=0;out=vs_agent_turn(&c,"implement safe change");if(!out||c.workflow.phase!=VS_WORKFLOW_AWAITING_ACCEPT){fprintf(stderr,"rejection setup failed: %s phase=%d\n",out?out:"(null)",c.workflow.phase);free(out);return 14;}free(out);vs_workflow_reject(&c.workflow);calls=1;out=vs_agent_turn(&c,"continue rejected work");if(!out||actions!=0||!strstr(out,"approval is required")){fprintf(stderr,"rejected plan allowed side effects: %s actions=%d\n",out?out:"(null)",actions);free(out);return 15;}free(out);question_mode=2;calls=0;memset(&c,0,sizeof(c));vs_workflow_init(&c.workflow);out=vs_agent_turn(&c,"legacy question");if(!out||!c.pending_question||c.question_option_count!=0||strcmp(out,"Legacy question")){fprintf(stderr,"legacy question-only marker failed: %s\n",out?out:"(null)");free(out);return 12;}free(out);question_mode=3;calls=0;memset(&c,0,sizeof(c));vs_workflow_init(&c.workflow);out=vs_agent_turn(&c,"malformed question");if(!out||!c.pending_question||c.question_option_count!=0||strcmp(out,"Malformed choices")){fprintf(stderr,"malformed options were not discarded: %s\n",out?out:"(null)");free(out);return 13;}free(out);question_mode=0;puts("agent workflow tests passed");return 0;}
